"jeevadhan.top.circularRuralEconomyRenewableAgriculture": "చక్రీయ గ్రామీణ ఆర్థిక వ్యవస్థ & పునరుత్పాదక వ్యవసాయం",
"jeevadhan.top.turningRuralBiomassIntoRenewable": "గ్రామీణ బయోమాస్‌ను పునరుత్పాదక విలువగా మార్చడం — స్థానికంగా దొరికే పశువుల బయోమాస్‌ను ఉపయోగకరమైన పునరుత్పాదక శక్తి మరియు వ్యవసాయ వనరులుగా మార్చడం.",
"jeevadhan.top.transformRuralBiomassFromA": "“గ్రామీణ బయోమాస్‌ను వ్యర్థ సమస్య నుంచి శక్తి, విలువ మరియు వ్యవసాయ సుస్థిరతకు మూలంగా మార్చండి.”",
