"jeevadhan.overview.needForSustainableOrganicresourceManagement": "సేంద్రియ వనరుల సుస్థిర నిర్వహణ అవసరం",
"jeevadhan.overview.lostOpportunityToRecoverBiological": "వ్యవసాయం కోసం జీవ వనరులను తిరిగి పొందే అవకాశం కోల్పోతున్నాం",
