"diary.top.theTaglineInSixIndian": "ఆరు భారతీయ భాషల్లో ట్యాగ్‌లైన్. హిందీ: हर खेत की कहानी, अब आपकी डायरी में. కన్నడ: ಪ್ರತಿ ಹೊಲದ ಕಥೆ, ಈಗ ನಿಮ್ಮ ಡೈರಿಯಲ್ಲಿ. తమిళం: ஒவ்வொரு வயலின் கதையும், இப்போது உங்கள் டைரியில். తెలుగు: ప్రతి పొలం కథ, ఇప్పుడు మీ డైరీలో. మరాఠీ: प्रत्येक शेताची कहाणी, आता तुमच्या डायरीत. మలయాళం: ഓരോ കൃഷിയിടത്തിന്റെയും കഥ, ഇനി നിങ്ങളുടെ ഡയറിയിൽ.",
