"diary.designed.ideaOneScreenShowsTodays": "<t0>ఆలోచన:</t0> ఈ రోజు రికార్డులు, విత్తి ఎన్ని రోజులైంది, ఏమి ప్లాన్ చేశారు — అన్నీ ఒకే స్క్రీన్‌లో కనిపిస్తాయి.",
"diary.designed.onetapRecord": "ఒక్క తాకింపుతో రికార్డు",
"diary.designed.farmerProblemTypingInThe": "<t0>రైతు సమస్య:</t0> పొలంలో టైప్ చేయడం నెమ్మది — చేతులకు మట్టి ఉంటుంది, ఎండ తీవ్రంగా ఉంటుంది.",
"diary.designed.ideaBigPictureButtonsRecord": "<t0>ఆలోచన:</t0> ఎక్కువగా చేసే పనులను పెద్ద బొమ్మల బటన్లతో ఒకటి రెండు తాకింపుల్లో నమోదు చేయవచ్చు.",
"diary.designed.cropMemory": "పంట జ్ఞాపకం",
"diary.designed.farmerProblemWithSeveralCrops": "<t0>రైతు సమస్య:</t0> చాలా పంటలు ఉంటే రికార్డులు కలిసిపోయి గందరగోళం అవుతాయి.",
"diary.designed.ideaEveryRecordIsFiled": "<t0>ఆలోచన:</t0> ప్రతి రికార్డు దానంతట అదే దాని పంట, పొలం కింద చేరుతుంది.",
"diary.designed.seasonBook": "సీజన్ పుస్తకం",
"diary.designed.farmerProblemPaperNotebooksGet": "<t0>రైతు సమస్య:</t0> కాగితం పుస్తకాలు పోతాయి లేదా పాడవుతాయి.",
"diary.designed.ideaACompletePrintableRecord": "<t0>ఆలోచన:</t0> మొత్తం సీజన్‌కు పూర్తి, ప్రింట్ చేయగలిగే రికార్డు.",
"diary.designed.farmPassport": "పొలం పాస్‌పోర్ట్",
"diary.designed.farmerProblemFarmHistoryIs": "<t0>రైతు సమస్య:</t0> పొలం చరిత్ర ఏళ్ళ తరబడి, ఎన్నో పుస్తకాల్లో చెల్లాచెదురుగా ఉంటుంది.",
"diary.designed.ideaSeasonBooksStackInto": "<t0>ఆలోచన:</t0> సీజన్ పుస్తకాలు ఒకదాని తర్వాత ఒకటి చేరి అదే భూమికి దీర్ఘకాల చరిత్ర అవుతాయి.",
"diary.designed.shareMyFarmRecord": "నా పొలం రికార్డు పంచుకోవడం",
"diary.designed.farmerProblemExplainingPastWork": "<t0>రైతు సమస్య:</t0> గతంలో చేసిన పనిని కుటుంబానికి, కొనుగోలుదారులకు లేదా అధికారులకు వివరించడం కష్టం.",
"diary.designed.ideaTheFarmerChoosesWhich": "<t0>ఆలోచన:</t0> ఏ రికార్డులు పంచుకోవాలో రైతే ఎంచుకుంటారు — ఏదీ దానంతట అదే పంచుకోబడదు.",
"diary.designed.voiceNotes": "వాయిస్ గమనికలు",
"diary.designed.farmerProblemNotEveryFarmer": "<t0>రైతు సమస్య:</t0> ప్రతి రైతుకూ టైప్ చేయడం సులభం కాదు.",
"diary.designed.ideaSpeakAShortNote": "<t0>ఆలోచన:</t0> మీ సొంత భాషలో చిన్న గమనిక చెప్పండి, దాన్ని రికార్డుతో పాటు ఉంచుకోండి.",
"diary.designed.offlinefirst": "ఇంటర్నెట్ లేకున్నా",
"diary.designed.farmerProblemMobileSignalIn": "<t0>రైతు సమస్య:</t0> పొలంలో మొబైల్ సిగ్నల్ బలహీనంగా ఉంటుంది లేదా అసలు ఉండదు.",
"diary.designed.ideaRecordsSaveOnThe": "<t0>ఆలోచన:</t0> రికార్డులు ముందుగా ఫోన్‌లోనే సేవ్ అవుతాయి, ఇంటర్నెట్ లేకున్నా పనిచేస్తాయి.",
